"use strict";
import { Link } from "react-router-dom";
import styled from "styled-components";
import { Flex, Text, useMedia } from "ui/src";
const Button = styled.button`
  all: unset;
  padding: 4px 6px;
  background-color: ${({ theme }) => theme.surface2};
  border-radius: 10px;
  border: 1px solid ${({ theme }) => theme.surface3};
  transition: all 0.2s ease;
  cursor: ${({ $isDisabled }) => $isDisabled ? "not-allowed" : "pointer"};
  display: flex;
  justify-content: center;
  align-items: center;
  &:hover {
    background-color: ${({ theme, $isDisabled }) => $isDisabled ? theme.surface2 : theme.surface2Hovered};
  }
`;
export default function IncreaseExtendMergeTransferReset({
  lockId,
  isReadyToUnlock,
  hasVoted = false,
  lockedInRelay = false
}) {
  const media = useMedia();
  const lockUrls = [
    {
      url: `/locks/modify-lock?lockId=${lockId}&tab=Increase`,
      label: "Increase"
    },
    {
      url: `/locks/modify-lock?lockId=${lockId}&tab=Extend`,
      label: "Extend"
    },
    {
      url: `/locks/modify-lock?lockId=${lockId}&tab=Merge`,
      label: "Merge"
    },
    {
      url: `/locks/modify-lock?lockId=${lockId}&tab=Transfer`,
      label: "Transfer"
    }
  ].map((item) => ({
    ...item,
    disabled: lockedInRelay
  }));
  if (hasVoted) {
    lockUrls.push({
      url: `/locks/modify-lock?lockId=${lockId}&tab=Reset`,
      label: "Reset Vote"
    });
  }
  return <Flex
    opacity={isReadyToUnlock && !hasVoted ? 0.25 : 1}
    row
    columnGap={"$spacing8"}
    rowGap={"$gap4"}
    alignItems="center"
    flexWrap="nowrap"
  >
      {lockUrls.map((item, index) => {
    const shouldDisable = isReadyToUnlock && item.label !== "Reset Vote" || item.disabled;
    return <Flex key={index} opacity={shouldDisable ? 0.25 : 1}>
            <Link className="text-decoration-none" to={shouldDisable ? "" : item.url}>
              <Button $isDisabled={shouldDisable}>
                <Text
      variant={media.md ? "buttonLabel4" : "buttonLabel4"}
      color={"$neutral1Hovered"}
      transition="all 250ms ease"
      hoverStyle={{ color: "$neutral1" }}
    >
                  {item.label}
                </Text>
              </Button>
            </Link>
          </Flex>;
  })}
    </Flex>;
}
